/// Removes one retired app-seeded `<name>/SKILL.md` — and, issue #1334, the
/// skill directory itself when it is left EMPTY: an empty `<name>/` under
/// `.fah/skills` is invisible to discovery but loudly visible to an
/// exploring agent, reading as "skills materialize as empty directories".
/// The empty-dir prune also fires when the copy is already gone, so
/// devices retired by older builds (which left the ghost dirs behind)
/// merge LAST — every on-disk skill of the same name shadows them — and
/// [skillToggles] (the app store's `skills:`-shaped wishes; the single
/// app-side scope, project config.yaml toggles are NOT read here) filter
/// the discovered list down to the enabled skills.
///
/// Returns the composed prompt suffix AND the enabled skills (gh-1409:
/// hosts republish them onto the agent so the operative-pin registry
/// rebuilds from the same list the prompt index renders).
Future<(String, List<Skill>)> _discoverPromptSuffix(
  ExecutionEnv env,
  SkillsAccess access, {
  String? homeDir,
  Map<String, bool> skillToggles = const {},
}) async {
  // User-level roots (~/.claude/skills, ~/.copilot/skills, ...) need the
  // real home directory - without it the desktop app only ever saw
  // project-local skills no matter what the consent said.
  final roots = defaultSkillRoots(
    cwd: env.cwd,
    homeDir: homeDir ?? desktopHomeDir(),
  );
  final skills = await discoverSkills(
    env,
    projectRoots: roots.projectRoots,
    userRoots: roots.userRoots,
    allowedSources: skillsAccessAllowsDiscovery(access, interactive: false)
        ? null
        : const {SkillSource.fah, SkillSource.agents},
    builtins: builtinSkills(),
  );
  final resolution = resolveSkillAvailability(
    skills: skills,
    scopes: [(SkillToggleScope.project, SkillsConfig(skills: skillToggles))],
  );
  final enabled = enabledSkills(skills, resolution);
  final context = await loadProjectContextFiles(env);
  // Issue #1761 AC2: the app's boot notice seam is AppLog (same rule as
  // the operative-pin notices) — truncation of project rules is never
  // silent here either.
  for (final notice in context.notices) {
    AppLog.i('context', notice);
  }
  final contextSection = formatProjectContext(context);
  final suffix = [
    if (contextSection.isNotEmpty) contextSection,
    if (formatSkillsForPrompt(enabled).isNotEmpty)
      formatSkillsForPrompt(enabled),
  ].join('\n\n');
  return (suffix, enabled);
}

