          notes.add('projectContext.$key: unknown key (ignored)');
      }
    });
    if (maxBytes < 0) {
      notes.add('projectContext.maxBytes: negative, treated as 0 (disabled)');
      maxBytes = 0;
    }
    return ProjectContextConfig(
      maxBytes: maxBytes,
      notes: List.unmodifiable(notes),
    );
  }
}

