            '${_sizeLabel(budgetBytes)} budget '
            '(full file stays on disk)',
    for (final drop in dropped)
      'project context truncated: ${_baseName(drop.path)} '
          '${_sizeLabel(drop.bytes)} dropped '
          '(full file stays on disk)',
  ];
}

