void _validateImagesSection(Object? node) {
  if (node is! YamlMap) {
    throw ConfigException('must be a map, got: $node');
  }
  for (final entry in node.entries) {
    final key = '${entry.key}';
    switch (key) {
      case 'registry':
        if (entry.value is! bool) {
          throw ConfigException('"images.registry" must be a boolean');
