/// Mirrors the boot parser's mode branch (issue #680): the shared
/// [agentLoadModeValidationError] rule — the same one the boot parser in
/// `cli_config.dart` applies, one source, no drift. `default` is legal
/// and explicit — the written file stays parseable.
void _validateAgentModeValue(Object? value) {
  final error = agentLoadModeValidationError(value);
  if (error != null) throw ConfigException(error);
}

/// Mirrors the strict private parser in `cli_config.dart` (pinned by
/// test).
void _validateImagesSection(Object? node) {
  if (node is! YamlMap) {
    throw ConfigException('must be a map, got: $node');
  }
  for (final entry in node.entries) {
    final key = '${entry.key}';
    switch (key) {
      case 'registry':
        if (entry.value is! bool) {
          throw ConfigException('"images.registry" must be a boolean');
        }
      case 'maxPerRequest':
        final value = entry.value;
        if (value is! int || value <= 0) {
          throw ConfigException(
            '"images.maxPerRequest" must be a positive integer',
          );
        }
      default:
        throw ConfigException('unknown "images" key: $key');
    }
  }
}

/// Mirrors the strict private parser in `cli_config.dart` (pinned by test).
void _validateSkillsSection(Object? node) {
  if (node is! YamlMap) {
    throw ConfigException('must be a map, got: $node');
  }
  for (final entry in node.entries) {
    switch ('${entry.key}') {
      case 'access':
        final value = '${entry.value}'.trim();
        if (!{'ask', 'granted', 'denied'}.contains(value)) {
          throw ConfigException(
            'skills.access must be ask, granted or denied, got: $value',
          );
        }
      case 'disableShellExecution':
        if (entry.value is! bool) {
          throw ConfigException(
            'skills.disableShellExecution must be a boolean',
          );
        }
      default:
        // A per-skill on/off toggle (issue #1151): any non-reserved key is
        // a skill name; the value must be on/off or a boolean.
        skillToggleValue('${entry.key}', entry.value);
    }
  }
}

